    two_positions = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 3:
                three_positions.append((r, c))
            elif grid[r][c] == 2:
                two_positions.append((r, c))

    if not three_positions or not two_positions:
        return grid

    # Determine centroid positions
    three_r_avg = sum(p[0] for p in three_positions) / len(three_positions)
    three_c_avg = sum(p[1] for p in three_positions) / len(three_positions)
    two_r_avg = sum(p[0] for p in two_positions) / len(two_positions)
    two_c_avg = sum(p[1] for p in two_positions) / len(two_positions)

    # Check orientation
    three_horizontal = (max(p[0] for p in three_positions) - min(p[0] for p in three_positions)) >= (max(p[1] for p in three_positions) - min(p[1] for p in three_positions))
    two_horizontal = (max(p[0] for p in two_positions) - min(p[0] for p in two_positions)) >= (max(p[1] for p in two_positions) - min(p[1] for p in two_positions))

    # For vertical pairs: horizontal first then vertical
    if not three_horizontal and not two_horizontal:
        corner_row = max(r for r, c in three_positions)
        corner_col = min(c for r, c in two_positions)

        # Draw horizontal from 3s rightmost to 2s leftmost, at row = max(3s_rows)
        if corner_col > min(c for r, c in three_positions):
            for c in range(min(c for r, c in three_positions) + 1, corner_col):
                if 0 <= corner_row < h and 0 <= c < w:
                    if grid[corner_row][c] not in (2, 3):
